function sortBy(rows, key, dir) {
  const flip = dir === "desc" ? -1 : 1;
  return rows.slice().sort((a, b) => {
    if (a[key] < b[key]) return -1 * flip;
    if (a[key] > b[key]) return 1 * flip;
    return 0;
  });
}

