function parseCSV(text) {
  const lines = text.split("\n").filter(l => l !== "");
  const keys = lines[0].split(",");
  return lines.slice(1).map(line => {
    const cells = line.split(",");
    const row = {};
    keys.forEach((k, i) => { row[k] = cells[i]; });
    return row;
  });
}

