let tasks = [
  { id: 1, text: "Feed the cat", done: true },
  { id: 2, text: "Maths homework", done: false },
  { id: 3, text: "Pack PE kit", done: false }
];
const list = document.querySelector("#list");
const count = document.querySelector("#count");
let lastRemoved = null;
const toast = document.querySelector("#toast");

function render() {
  list.innerHTML = "";
  for (const t of tasks) {
    const li = document.createElement("li");
    li.dataset.id = t.id;
    const span = document.createElement("span");
    span.textContent = t.text;
    span.style.flex = "1";
    const del = document.createElement("button");
    del.className = "del";
    del.textContent = "✕";
    li.append(span, del);
    list.append(li);
  }
  count.textContent = tasks.length + " tasks";
}

list.addEventListener("click", e => {
  if (!e.target.matches(".del")) return;
  const id = Number(e.target.closest("li").dataset.id);
  const pos = tasks.findIndex(t => t.id === id);
  lastRemoved = { task: tasks[pos], pos: pos };
  tasks.splice(pos, 1);
  render();
  document.querySelector("#toastMsg").textContent = "Deleted: " + lastRemoved.task.text;
  toast.hidden = false;
});

document.querySelector("#undo").addEventListener("click", () => {
  if (!lastRemoved) return;
  tasks.splice(lastRemoved.pos, 0, lastRemoved.task);
  lastRemoved = null;
  render();
  toast.hidden = true;
});

render();

