function playNote(freq) {
  const osc = audio.createOscillator();
  const vol = audio.createGain();
  osc.type = "triangle";
  osc.frequency.value = freq;
  vol.gain.value = 0.2;
  osc.connect(vol);
  vol.connect(audio.destination);
  osc.start();
  osc.stop(audio.currentTime + 0.3);
  return osc;
}

