let items = [];
let nextId = 1;
const list = document.querySelector("#list");
const err = document.querySelector("#err");

function barRow(cat, amount, max) {
  const pct = Math.round(amount / max * 100);
  return '<div class="row"><b>' + cat + '</b><div class="fill" style="width:' + pct + '%"></div></div>';
}
function money(n) {
  return new Intl.NumberFormat("en-US", { style: "currency", currency: "USD" }).format(n);
}
function byCategory(items) {
  const totals = {};
  for (const it of items) totals[it.cat] = (totals[it.cat] || 0) + it.amount;
  return totals;
}

function render() {
  list.innerHTML = "";
  for (const it of items) {
    const li = document.createElement("li");
    li.dataset.id = it.id;
    li.innerHTML = '<span style="flex:1"></span><b></b><button class="del">✕</button>';
    li.querySelector("span").textContent = it.what + " (" + it.cat + ")";
    li.querySelector("b").textContent = money(it.amount);
    list.append(li);
  }
  const sum = items.reduce((s, it) => s + it.amount, 0);
  document.querySelector("#total").textContent = money(sum);
  document.querySelector("#empty").hidden = items.length > 0;
  const totals = byCategory(items);
  const max = Math.max(...Object.values(totals));
  document.querySelector("#bars").innerHTML = Object.keys(totals).map(c => barRow(c, totals[c], max)).join("");
}

document.querySelector("#add").addEventListener("submit", e => {
  e.preventDefault();
  const what = document.querySelector("#what").value.trim();
  const amount = Number(document.querySelector("#amount").value);
  const cat = document.querySelector("#cat").value;
  if (what === "" || !(amount > 0)) {
    err.textContent = "Add a name and an amount above 0.";
    return;
  }
  err.textContent = "";
  items.push({ id: nextId++, what: what, amount: amount, cat: cat });
  document.querySelector("#what").value = "";
  document.querySelector("#amount").value = "";
  render();
});

list.addEventListener("click", e => {
  if (!e.target.matches(".del")) return;
  const id = Number(e.target.closest("li").dataset.id);
  items = items.filter(it => it.id !== id);
  render();
});

render();

